+import { describe, it, expect, beforeEach, vi } from 'vitest';
+
+import type { ImageObject, CanvasObject } from '@/components/canvas/types';
+import type { SelectionItem } from '@/hooks/use-selection-state';
+import { PLACEHOLDER_IMAGE_SRC } from '@/constants/canvas';
+
+import {
+  ChatAttachment,
+  MAX_CHAT_ATTACHMENT_UI_LIMIT,
+  getContentTypeFromUrl,
+  isValidImageSrc,
+  imageObjectToAttachment,
+  buildCanvasAttachmentsFromSelection,
+  resizeImageToDataUrl
+} from '@/lib/chat-image-utils';
+
+// ---------------------------------------------------------------------------
+// Mocks (for resizeImageToDataUrl browser-API tests)
+// ---------------------------------------------------------------------------
+
+let capturedOnload: (() => void) | null = null;
+let capturedOnerror: (() => void) | null = null;
+let capturedSrc: string | null = null;
+
+const mockImageInstance = {
+  set onload(fn: () => void) {
+    capturedOnload = fn;
+  },
+  set onerror(fn: () => void) {
+    capturedOnerror = fn;
+  },
+  set src(value: string) {
+    capturedSrc = value;
+  },
+  get src() {
+    return capturedSrc ?? '';
+  },
+  width: 0,
+  height: 0
+};
+
+vi.stubGlobal(
+  'Image',
+  vi.fn(function () { return mockImageInstance; })
+);
+
+const mockDrawImage = vi.fn();
+const mockToDataURL = vi.fn(() => 'data:image/jpeg;base64,mock');
+const mockGetContext = vi.fn();
+
+const mockCanvasElement = {
+  width: 0,
+  height: 0,
+  getContext: mockGetContext,
+  toDataURL: mockToDataURL
+};
+
+const originalCreateElement = document.createElement.bind(document);
+vi.spyOn(document, 'createElement').mockImplementation((tag: string) => {
+  if (tag === 'canvas') {
+    return mockCanvasElement as unknown as HTMLCanvasElement;
+  }
+  return originalCreateElement(tag);
+});
+
+const mockCreateObjectURL = vi.fn(() => 'blob:mock-url');
+const mockRevokeObjectURL = vi.fn();
+
+// Preserve the URL constructor (needed by isValidImageSrc) while mocking
+// createObjectURL / revokeObjectURL (needed by resizeImageToDataUrl).
+const OriginalURL = globalThis.URL;
+vi.stubGlobal('URL', Object.assign(
+  function UrlShim(input: string | URL, base?: string | URL) {
+    return new OriginalURL(input, base);
+  } as unknown as typeof URL,
+  {
+    ...OriginalURL,
+    prototype: OriginalURL.prototype,
+    createObjectURL: mockCreateObjectURL,
+    revokeObjectURL: mockRevokeObjectURL
+  }
+));
+
+// ---------------------------------------------------------------------------
+// Helpers
+// ---------------------------------------------------------------------------
+
+function createFakeFile(name: string): File {
+  return new File(['fake'], name, { type: 'image/png' });
+}
+
+/** Simulate the Image onload with the given natural dimensions. */
+function triggerLoad(width: number, height: number) {
+  mockImageInstance.width = width;
+  mockImageInstance.height = height;
+  capturedOnload!();
+}
+
+function triggerError() {
+  capturedOnerror!();
+}
+
+/** Build a minimal ImageObject for testing. */
+function makeImage(
+  overrides: Partial<ImageObject> & { id: string; src: string | string[] }
+): ImageObject {
+  return {
+    position: { x: 0, y: 0 },
+    width: 100,
+    height: 100,
+    type: 'image' as const,
+    ...overrides
+  };
+}
+
+/** Build a ChatAttachment for testing. */
+function makeUpload(id: string): ChatAttachment {
+  return {
+    id,
+    name: `upload-${id}.png`,
+    contentType: 'image/png',
+    url: `data:image/png;base64,${id}`,
+    source: 'upload'
+  };
+}
+
+// ---------------------------------------------------------------------------
+// Tests
+// ---------------------------------------------------------------------------
+
+describe('chat-image-utils', () => {
+  beforeEach(() => {
+    vi.clearAllMocks();
+    capturedOnload = null;
+    capturedOnerror = null;
+    capturedSrc = null;
+    mockGetContext.mockReturnValue({ drawImage: mockDrawImage });
+  });
+
+  // =========================================================================
+  // MAX_CHAT_ATTACHMENT_UI_LIMIT constant
+  // =========================================================================
+
+  it('MAX_CHAT_ATTACHMENT_UI_LIMIT is 50', () => {
+    expect(MAX_CHAT_ATTACHMENT_UI_LIMIT).toBe(50);
+  });
+
+  // =========================================================================
+  // getContentTypeFromUrl
+  // =========================================================================
+
+  describe('getContentTypeFromUrl', () => {
+    it('returns image/png for .png URLs', () => {
+      expect(getContentTypeFromUrl('https://cdn.example.com/photo.png')).toBe(
+        'image/png'
+      );
+    });
+
+    it('returns image/webp for .webp URLs', () => {
+      expect(getContentTypeFromUrl('https://cdn.example.com/photo.webp')).toBe(
+        'image/webp'
+      );
+    });
+
+    it('returns image/gif for .gif URLs', () => {
+      expect(getContentTypeFromUrl('https://cdn.example.com/anim.gif')).toBe(
+        'image/gif'
+      );
+    });
+
+    it('returns image/jpeg for .jpg URLs', () => {
+      expect(getContentTypeFromUrl('https://cdn.example.com/photo.jpg')).toBe(
+        'image/jpeg'
+      );
+    });
+
+    it('returns image/jpeg for .jpeg URLs', () => {
+      expect(getContentTypeFromUrl('https://cdn.example.com/photo.jpeg')).toBe(
+        'image/jpeg'
+      );
+    });
+
+    it('returns image/jpeg as default for unknown extensions', () => {
+      expect(getContentTypeFromUrl('https://cdn.example.com/photo.bmp')).toBe(
+        'image/jpeg'
+      );
+      expect(getContentTypeFromUrl('https://cdn.example.com/photo.tiff')).toBe(
+        'image/jpeg'
+      );
+    });
+
+    it('handles URLs with query params', () => {
+      expect(
+        getContentTypeFromUrl('https://cdn.example.com/photo.png?v=123&w=800')
+      ).toBe('image/png');
+    });
+
+    it('handles URLs with query params on webp', () => {
+      expect(
+        getContentTypeFromUrl('https://cdn.example.com/photo.webp?quality=80')
+      ).toBe('image/webp');
+    });
+
+    it('is case-insensitive for extensions', () => {
+      expect(getContentTypeFromUrl('https://cdn.example.com/photo.PNG')).toBe(
+        'image/png'
+      );
+      expect(getContentTypeFromUrl('https://cdn.example.com/photo.WEBP')).toBe(
+        'image/webp'
+      );
+      expect(getContentTypeFromUrl('https://cdn.example.com/photo.GIF')).toBe(
+        'image/gif'
+      );
+    });
+  });
+
+  // =========================================================================
+  // isValidImageSrc
+  // =========================================================================
+
+  describe('isValidImageSrc', () => {
+    it('returns true for https:// URLs', () => {
+      expect(isValidImageSrc('https://cdn.example.com/img.png')).toBe(true);
+    });
+
+    it('returns true for http:// URLs', () => {
+      expect(isValidImageSrc('http://cdn.example.com/img.png')).toBe(true);
+    });
+
+    it('returns true for data: URLs', () => {
+      expect(isValidImageSrc('data:image/png;base64,abc123')).toBe(true);
+    });
+
+    it('returns true for blob: URLs', () => {
+      expect(isValidImageSrc('blob:http://localhost/some-uuid')).toBe(true);
+    });
+
+    it('returns false for undefined', () => {
+      expect(isValidImageSrc(undefined)).toBe(false);
+    });
+
+    it('returns false for empty string', () => {
+      expect(isValidImageSrc('')).toBe(false);
+    });
+
+    it('returns false for relative paths', () => {
+      expect(isValidImageSrc('/images/photo.png')).toBe(false);
+      expect(isValidImageSrc('./photo.png')).toBe(false);
+      expect(isValidImageSrc('photo.png')).toBe(false);
+    });
+
+    it('returns false for non-image protocols', () => {
+      expect(isValidImageSrc('ftp://example.com/file.png')).toBe(false);
+      expect(isValidImageSrc('file:///local/path.png')).toBe(false);
+    });
+
+    it('handles array src — uses first element', () => {
+      expect(
+        isValidImageSrc(['https://cdn.example.com/img.png', 'https://other.com/img2.png'])
+      ).toBe(true);
+    });
+
+    it('returns false for array with empty first element', () => {
+      expect(isValidImageSrc([''])).toBe(false);
+    });
+
+    it('returns false for empty array', () => {
+      expect(isValidImageSrc([] as unknown as string[])).toBe(false);
+    });
+
+    it('handles array where first element is invalid', () => {
+      expect(isValidImageSrc(['/relative/path.png'])).toBe(false);
+    });
+  });
+
+  // =========================================================================
+  // imageObjectToAttachment
+  // =========================================================================
+
+  describe('imageObjectToAttachment', () => {
+    it('converts ImageObject with string src', () => {
+      const image = makeImage({
+        id: 'img-1',
+        src: 'https://cdn.example.com/photo.png',
+        userPrompt: 'A red cat'
+      });
+
+      const attachment = imageObjectToAttachment(image);
+
+      expect(attachment).toEqual({
+        id: 'img-1',
+        name: 'A red cat',
+        contentType: 'image/png',
