+        ).contentType
+      ).toBe('image/jpeg');
+    });
+  });
+
+  // =========================================================================
+  // buildCanvasAttachmentsFromSelection (RED — function does not exist yet)
+  // =========================================================================
+
+  describe('buildCanvasAttachmentsFromSelection', () => {
