+'use client';
+
+import { memo } from 'react';
+import { RotateCcw } from 'lucide-react';
+import ReactMarkdown from 'react-markdown';
+import remarkGfm from 'remark-gfm';
+import { UIMessage } from 'ai';
+
+import { Button } from '@/components/ui/button';
+import { Avatar, AvatarImage, AvatarFallback } from '@/components/ui/avatar';
+import { UserProfileIcon } from '@/components/nav/user-profile-icon';
+import {
+  extractSuggestedReplies,
+  removeSuggestedReplies
+} from '@/utils/suggested-replies';
+import { GAZAI_CHAN_CHIBI_NO_BG } from '@/constants';
+import { useTranslations } from 'next-intl';
+
+import { SuggestionReplyButton } from './suggestion-reply-button';
+
+// Suggested replies component for individual messages
+interface SuggestedRepliesForMessageProps {
+  message: UIMessage;
+  onSuggestionClick: (suggestion: string) => void;
+  disabled: boolean;
+}
+
+const SuggestedRepliesForMessage = ({
+  message,
+  onSuggestionClick,
+  disabled
+}: SuggestedRepliesForMessageProps) => {
+  // Extract suggested replies from the message content using utility function
+  const content = message.content || '';
+  const suggestedReplies = extractSuggestedReplies(content);
+
+  // Don't render if no suggestions
+  if (!suggestedReplies || suggestedReplies.length === 0) return null;
+
+  return (
+    <div className="mt-3 flex flex-wrap gap-2">
+      {suggestedReplies.map((suggestion, index) => (
+        <SuggestionReplyButton
+          key={`${suggestion}-${index}`}
+          suggestion={suggestion}
+          onClick={onSuggestionClick}
+          disabled={disabled}
+        />
+      ))}
+    </div>
+  );
+};
+
+export interface ChatMessageBubbleProps {
+  message: UIMessage;
+  sessionUser: { image?: string | null; name?: string | null };
+  isLastMessage: boolean;
+  isDisabled: boolean;
+  status: 'streaming' | 'submitted' | 'ready' | 'error';
+  onSuggestionClick: (suggestion: string) => void;
+  onReload: () => void;
+  getTranslatedToolName: (toolName: string) => string;
+}
+
+export const ChatMessageBubble = memo(function ChatMessageBubble({
+  message,
+  sessionUser,
+  isLastMessage,
+  isDisabled,
+  status,
+  onSuggestionClick,
+  onReload,
+  getTranslatedToolName,
+}: ChatMessageBubbleProps) {
+  const t = useTranslations('Canvas.chat');
+
+  return (
+    <div
+      data-message-id={message.id}
+      className={`flex items-start gap-2 ${
+        message.role === 'user' ? 'flex-row-reverse' : 'flex-row'
+      }`}
+    >
+      {message.role === 'user' ? (
+        <Avatar>
+          <AvatarFallback className="text-primary-foreground">
+            <UserProfileIcon
+              userImage={sessionUser.image ?? ''}
+              userName={sessionUser.name ?? ''}
+            />
+          </AvatarFallback>
+        </Avatar>
+      ) : (
+        <Avatar>
+          <AvatarImage
+            src={GAZAI_CHAN_CHIBI_NO_BG}
+            alt={t('gazaiChan')}
+          />
+          <AvatarFallback>GJ</AvatarFallback>
+        </Avatar>
+      )}
+      <div className="flex flex-col gap-2 max-w-[75%] ">
+        <div
+          className={`rounded-lg px-4 py-2 space-y-2 ${
+            message.role === 'user'
+              ? 'bg-primary text-primary-foreground rounded-tr-none'
+              : 'bg-muted rounded-tl-none'
+          }`}
+        >
+          {/* Render message content or tool invocations */}
+          {message.parts?.map((part, index) => {
+            if (part.type === 'text') {
+              // Clean the text content by removing SUGGESTED_REPLIES section
+              const cleanText = removeSuggestedReplies(part.text);
+
+              // Only render if there's content after cleaning
+              if (cleanText) {
+                return (
+                  <div
+                    key={index}
+                    className={`prose prose-sm dark:prose-invert max-w-none ${
+                      message.role === 'user'
+                        ? 'text-primary-foreground'
+                        : 'text-muted-foreground'
+                    }`}
+                  >
+                    <ReactMarkdown remarkPlugins={[remarkGfm]}>
+                      {cleanText}
+                    </ReactMarkdown>
+                  </div>
+                );
+              }
+              return null;
+            } else if (part.type === 'tool-invocation') {
+              const toolInvocation = part.toolInvocation;
+
+              switch (toolInvocation.state) {
+                case 'call':
+                  return (
+                    <div
+                      key={index}
+                      className="text-xs bg-muted-foreground/10 p-2 rounded my-2"
+                    >
+                      <span className="font-semibold">
+                        {t('executing', {
+                          toolName: getTranslatedToolName(
+                            toolInvocation.toolName
+                          )
+                        })}
+                      </span>
+                      {toolInvocation.toolName ===
+                        'generateImage' && (
+                        <div className="text-xs text-muted-foreground mt-1">
+                          {t('promptTranslationNote')}
+                        </div>
+                      )}
+                      <pre className="text-xs mt-1 overflow-x-auto">
+                        {JSON.stringify(toolInvocation.args, null, 2)}
+                      </pre>
+                    </div>
+                  );
+                case 'result': {
+                  // Check if this is an error (including object limit error)
+                  const isError =
+                    (typeof toolInvocation.result === 'string' &&
+                      toolInvocation.result.startsWith('Error:')) ||
+                    (typeof toolInvocation.result === 'object' &&
+                      toolInvocation.result &&
+                      'error' in toolInvocation.result &&
+                      typeof toolInvocation.result.error ===
+                        'string');
+
+                  return (
+                    <div
+                      key={index}
+                      className={`text-xs ${
+                        isError ? 'bg-red-500/10' : 'bg-green-500/10'
+                      } p-2 rounded my-2`}
+                    >
+                      <span
+                        className={`font-semibold ${
+                          isError ? 'text-red-600' : 'text-green-600'
+                        }`}
+                      >
+                        {t('executeResult', {
+                          icon: isError ? '✗' : '✓',
+                          toolName: getTranslatedToolName(
+                            toolInvocation.toolName
+                          ),
+                          status: isError
+                            ? t('toolStatus.failed')
+                            : t('toolStatus.completed')
+                        })}
+                      </span>
+                      {toolInvocation.result && (
+                        <div
+                          className={`text-xs mt-1 overflow-x-auto ${
+                            isError ? 'text-red-500' : ''
+                          }`}
+                        >
+                          {(() => {
+                            const isObjectLimitError =
+                              typeof toolInvocation.result ===
+                                'object' &&
+                              toolInvocation.result &&
+                              'error' in toolInvocation.result &&
+                              typeof toolInvocation.result.error ===
+                                'string' &&
+                              toolInvocation.result.error.includes(
+                                'Object limit reached'
+                              );
+
+                            return isObjectLimitError ? (
+                              <div className="whitespace-pre-wrap">
+                                {t('error.objectLimitReachedMessage')}
+                              </div>
+                            ) : typeof toolInvocation.result === 'object' &&
+                              toolInvocation.result &&
+                              'message' in toolInvocation.result &&
+                              toolInvocation.result.message ? (
+                              <div className="whitespace-pre-wrap">
+                                {toolInvocation.result.message as string}
+                              </div>
+                            ) : typeof toolInvocation.result ===
+                              'object' ? (
+                              <pre>
+                                {JSON.stringify(
+                                  toolInvocation.result,
+                                  null,
+                                  2
+                                )}
+                              </pre>
+                            ) : (
+                              <pre>{toolInvocation.result}</pre>
+                            );
+                          })()}
+                        </div>
+                      )}
+                    </div>
+                  );
+                }
+                default:
+                  return null;
+              }
+            }
+            return null;
+          }) || (
+            <div className="prose prose-sm dark:prose-invert max-w-none">
+              <ReactMarkdown remarkPlugins={[remarkGfm]}>
+                {removeSuggestedReplies(message.content || '')}
+              </ReactMarkdown>
+            </div>
+          )}
+
+          {/* Show image attachments for user messages */}
+          {message.role === 'user' && message.experimental_attachments && message.experimental_attachments.length > 0 && (
+            <div className="flex flex-wrap gap-1 mt-2">
+              {message.experimental_attachments
+                .filter((a) => a.contentType?.startsWith('image/'))
+                .map((attachment, i) => (
+                  <div
+                    key={`${attachment.name}-${i}`}
+                    className="relative w-16 h-16 rounded-md overflow-hidden border border-primary-foreground/20"
+                  >
+                    <img
+                      src={attachment.url}
+                      alt={attachment.name || 'Attached image'}
+                      className="w-full h-full object-cover"
+                      onError={(e) => {
+                        e.currentTarget.style.display = 'none';
+                      }}
+                    />
+                    <div className="absolute top-0 left-0 min-w-[1.125rem] h-[1.125rem] flex items-center justify-center bg-black/60 text-white text-[10px] font-semibold rounded-br-md px-0.5">
+                      {i + 1}
+                    </div>
+                  </div>
+                ))}
+            </div>
+          )}
+
+          {/* Show suggested replies for AI messages */}
+          {message.role === 'assistant' && (
+            <SuggestedRepliesForMessage
+              message={message}
+              onSuggestionClick={onSuggestionClick}
+              disabled={isDisabled}
+            />
+          )}
+        </div>
+        {/* Show regenerate button for the last message */}
+        {message.role === 'assistant' &&
+          isLastMessage &&
+          status === 'ready' && (
+            <div className="flex items-center gap-2">
+              <Button
+                variant="default"
+                size="sm"
+                onClick={() => onReload()}
+                className="flex justify-center text-xs items-center gap-1"
+              >
+                <RotateCcw className="h-3.5 w-3.5" />
+                {t('regenerateResponse')}
+              </Button>
+            </div>
+          )}
+      </div>
+    </div>
+  );
+});
