+      });
+
+      expect(imageObjectToAttachment(image).name).toBe('Canvas image');
+    });
+
+    it('sets source to canvas', () => {
+      const image = makeImage({
+        id: 'img-5',
+        src: 'https://cdn.example.com/photo.gif'
+      });
+
+      expect(imageObjectToAttachment(image).source).toBe('canvas');
+    });
+
+    it('detects correct content type from URL', () => {
+      expect(
+        imageObjectToAttachment(
+          makeImage({ id: '1', src: 'https://x.com/a.png' })
+        ).contentType
+      ).toBe('image/png');
+
+      expect(
+        imageObjectToAttachment(
+          makeImage({ id: '2', src: 'https://x.com/a.webp' })
