+      ).toBe('image/webp');
+
+      expect(
+        imageObjectToAttachment(
+          makeImage({ id: '3', src: 'https://x.com/a.gif' })
+        ).contentType
+      ).toBe('image/gif');
+
+      expect(
+        imageObjectToAttachment(
+          makeImage({ id: '4', src: 'https://x.com/a.jpg' })
+        ).contentType
+      ).toBe('image/jpeg');
+    });
+  });
+
+  // =========================================================================
+  // buildCanvasAttachmentsFromSelection (RED — function does not exist yet)
+  // =========================================================================
+
+  describe('buildCanvasAttachmentsFromSelection', () => {
+    // Sample canvas objects for tests
+    const canvasObjects: CanvasObject[] = [
+      makeImage({
+        id: 'img-a',
+        src: 'https://cdn.example.com/a.png',
